import{_ as t,o as d,c as o,ah as a}from"./chunks/framework.rk_qxSDs.js";const u=JSON.parse('{"title":"Body Configuration","description":"Parser options for JSON, URL-encoded, raw and text bodies.","frontmatter":{"title":"Body Configuration","description":"Parser options for JSON, URL-encoded, raw and text bodies.","relatedPlugins":["basic"]},"headers":[],"relativePath":"body/configuration.md","filePath":"body/configuration.md","lastUpdated":1795602954000}'),c={name:"body/configuration.md"};function r(s,e,n,i,h,l){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p><code>body(options?)</code> takes one entry per format, the <code>Options</code> type. Each entry is an options object, <code>true</code> (enabled with the defaults below) or <code>false</code>.</p><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>json</code></td><td><code>JsonOptions | boolean</code></td><td><code>true</code> when no format is set</td><td>Parse JSON bodies in <code>readRequestBody()</code></td></tr><tr><td><code>urlEncoded</code></td><td><code>UrlEncodedOptions | boolean</code></td><td><code>true</code> when no format is set</td><td>Parse URL-encoded form bodies in <code>readRequestBody()</code></td></tr><tr><td><code>raw</code></td><td><code>RawOptions | boolean</code></td><td>none</td><td>Default options of <code>readRequestBodyBytes()</code>, <code>readRequestBodyArrayBuffer()</code> and <code>readRequestBodyBlob()</code></td></tr><tr><td><code>text</code></td><td><code>TextOptions | boolean</code></td><td>none</td><td>Default options of <code>readRequestBodyText()</code></td></tr><tr><td><code>strictContentType</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Answer <code>415</code> in <code>readRequestBody()</code> for a body whose content-type no enabled parser accepts (<a href="#strict-media-types">Strict Media Types</a>)</td></tr></tbody></table><p>When no entry is set at all, <code>body()</code> sets <code>json</code> and <code>urlEncoded</code> to <code>true</code> on the options object you passed. Once one entry is set, the others stay off: <code>body({ text: true })</code> enables only <code>text</code>, and <code>readRequestBody()</code> then returns <code>{}</code>. Set <code>json: true, urlEncoded: true</code> as well to keep them.</p><h3 id="strict-media-types" tabindex="-1">Strict Media Types <a class="header-anchor" href="#strict-media-types" aria-label="Permalink to &quot;Strict Media Types&quot;">​</a></h3><p>By default, <code>readRequestBody()</code> returns <code>{}</code> for a body of a media type no parser accepts, and parses a body without a content-type as JSON. With <code>strictContentType: true</code> it checks the content-type with routup&#39;s <a href="https://routup.dev/api/request-helpers" target="_blank" rel="noreferrer"><code>assertRequestContentType()</code></a> against the <code>type</code> lists of the enabled <code>json</code> and <code>urlEncoded</code> parsers: a missing or unlisted content-type answers <code>415</code>, a malformed one <code>400</code>. A request without a body is not checked and reads as <code>{}</code>. Whether it has one is decided by its framing: a <code>transfer-encoding</code> header or a <code>content-length</code> other than <code>0</code>, or, with neither header, a <code>content-type</code>. With neither <code>json</code> nor <code>urlEncoded</code> enabled, every body answers <code>415</code>. The other helpers do not check the content-type. <a href="/body/recipes#reject-other-media-types">Reject Other Media Types</a> shows it.</p><h3 id="size-limits" tabindex="-1">Size Limits <a class="header-anchor" href="#size-limits" aria-label="Permalink to &quot;Size Limits&quot;">​</a></h3><p>Every format takes <code>limit</code>: a number of bytes, or a string with the unit <code>b</code>, <code>kb</code>, <code>mb</code> or <code>gb</code> (1024-based, case-insensitive, such as <code>&#39;100kb&#39;</code> or <code>&#39;1.5mb&#39;</code>). Without <code>limit</code> there is no size limit.</p><ul><li>A <code>content-length</code> header above the limit answers <code>413</code> before anything is read.</li><li>The limit is checked again against the decoded bytes while the body is read, so a missing or wrong <code>content-length</code>, or a compressed body that expands, does not get past it.</li><li>A string with another unit is read as its leading number of bytes: <code>&#39;2 MiB&#39;</code> allows 2 bytes. A string without a leading number, such as <code>&#39;large&#39;</code>, makes every read answer <code>500</code>.</li></ul><h3 id="caching-the-bytes" tabindex="-1">Caching the Bytes <a class="header-anchor" href="#caching-the-bytes" aria-label="Permalink to &quot;Caching the Bytes&quot;">​</a></h3><p><code>cache: true</code> keeps the raw bytes on the request for later reads; the next helper that runs with <code>cache: true</code> returns them instead of reading the body again. Without it, a second read of a body already consumed answers <code>500</code> (<code>ReadableStream is locked</code>). The JSON and URL-encoded parsers always cache, whatever <code>cache</code> says. Leave it off for large uploads, so the bytes are not held in memory for the whole request. <a href="/body/recipes#verify-a-webhook-signature">Verify a Webhook Signature</a> reads the same body twice.</p><h3 id="json" tabindex="-1"><code>json</code> <a class="header-anchor" href="#json" aria-label="Permalink to &quot;`json`&quot;">​</a></h3><p>The JSON parser of <code>readRequestBody()</code>. An empty body gives <code>{}</code>.</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>limit</code></td><td><code>number | string</code></td><td>none</td><td>Maximum body size (<a href="#size-limits">Size Limits</a>)</td></tr><tr><td><code>cache</code></td><td><code>boolean</code></td><td>always on</td><td>The parser caches the raw bytes whatever this says</td></tr><tr><td><code>strict</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Only accept objects and arrays; any other JSON value answers <code>400</code></td></tr><tr><td><code>reviver</code></td><td><code>(key: string, value: unknown) =&gt; unknown</code></td><td>none</td><td>Passed to <code>JSON.parse</code></td></tr><tr><td><code>type</code></td><td><code>string | string[]</code></td><td><code>&#39;application/json&#39;</code></td><td>Content types to parse: a media type, a pattern such as <code>application/*+json</code>, or an extension such as <code>json</code>; parameters and case are ignored</td></tr></tbody></table><p>With <code>strict: false</code>, a primitive or <code>null</code> is the result of <code>readRequestBody()</code>, and a keyed read of it resolves to <code>undefined</code>.</p><h3 id="urlencoded" tabindex="-1"><code>urlEncoded</code> <a class="header-anchor" href="#urlencoded" aria-label="Permalink to &quot;`urlEncoded`&quot;">​</a></h3><p>The URL-encoded parser of <code>readRequestBody()</code>, for HTML forms. Fields that appear more than once become arrays (<code>tag=a&amp;tag=b</code> gives <code>{ tag: [&#39;a&#39;, &#39;b&#39;] }</code>); bracket keys such as <code>user[name]</code> stay flat keys and are not expanded into nested objects.</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>limit</code></td><td><code>number | string</code></td><td>none</td><td>Maximum body size (<a href="#size-limits">Size Limits</a>)</td></tr><tr><td><code>cache</code></td><td><code>boolean</code></td><td>always on</td><td>The parser caches the raw bytes whatever this says</td></tr><tr><td><code>parameterLimit</code></td><td><code>number</code></td><td><code>1000</code></td><td>Maximum number of fields; more answer <code>413</code></td></tr><tr><td><code>type</code></td><td><code>string | string[]</code></td><td><code>&#39;application/x-www-form-urlencoded&#39;</code></td><td>Content types to parse, as for <code>json</code></td></tr></tbody></table><h3 id="raw" tabindex="-1"><code>raw</code> <a class="header-anchor" href="#raw" aria-label="Permalink to &quot;`raw`&quot;">​</a></h3><p>Default options of <code>readRequestBodyBytes()</code>, <code>readRequestBodyArrayBuffer()</code> and <code>readRequestBodyBlob()</code> when they are called without options. Without <code>raw</code>, they read without a limit.</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>limit</code></td><td><code>number | string</code></td><td>none</td><td>Maximum body size (<a href="#size-limits">Size Limits</a>)</td></tr><tr><td><code>cache</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Keep the raw bytes for later reads (<a href="#caching-the-bytes">Caching the Bytes</a>)</td></tr><tr><td><code>type</code></td><td><code>string | string[]</code></td><td><code>&#39;application/octet-stream&#39;</code></td><td>Declared, but not checked: the helpers read any content type</td></tr></tbody></table><h3 id="text" tabindex="-1"><code>text</code> <a class="header-anchor" href="#text" aria-label="Permalink to &quot;`text`&quot;">​</a></h3><p>Default options of <code>readRequestBodyText()</code> when it is called without options. Without <code>text</code>, it reads without a limit and decodes UTF-8.</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>limit</code></td><td><code>number | string</code></td><td>none</td><td>Maximum body size (<a href="#size-limits">Size Limits</a>)</td></tr><tr><td><code>cache</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Keep the raw bytes for later reads (<a href="#caching-the-bytes">Caching the Bytes</a>)</td></tr><tr><td><code>defaultCharset</code></td><td><code>string</code></td><td><code>&#39;utf-8&#39;</code></td><td>Charset passed to <code>TextDecoder</code>; the request&#39;s <code>charset</code> parameter is not read</td></tr><tr><td><code>type</code></td><td><code>string | string[]</code></td><td><code>&#39;text/plain&#39;</code></td><td>Declared, but not checked: the helper reads any content type</td></tr></tbody></table>',25)])])}const y=t(c,[["render",r]]);export{u as __pageData,y as default};
